import React , {useEffect, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId, ObjectKeys, parseFloatToDecimal, updStore } from "../../../stores/Utils";
import {  get_filter_paystub } from "../services/server_fetching";
import { useNavigate } from "react-router";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, CalendarModalPicker_Cmpt } from "../../../components";
import { NavLink } from "react-router-dom";
import DeleteAlert from "../../Inventory/component/deleteAlert";
import { delete_Comprobante } from "../../Comprobantes/services/server_fetching";
import {  SumBalancePS } from "./ViewPayStubMayor";



const CalendarModalPicker = CalendarModalPicker_Cmpt();
const Svg = SvgIcon_Cmpt();

const ViewComprobante  = ({ data, item }) => {
	const [, set_obs] = useState(0);


	
	useEffect(() => {
		//get_filter_by_acc(item,updObs);
	},[item]);

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}



	const navigate = useNavigate();

	const close =  (element) => {
		CloseModal({id:data.modalID});
	}
	


	const confirmCalendar = (v) => {
		if(v?.initDate && v?.lastDate ){
			let nv = {...v};
			nv.initDate = nv.initDate -100;
			nv.lastDate = nv.lastDate + 86380000;
			updStore("date_range_comps",nv);
		}
		get_filter_paystub( item?.employeeId, updObs)
	}
	

    const openCalendar = () => {
        let modal_data = {};
        modal_data["zIndex"] = 950;
        modal_data["height"] = "80vh";
        // data['observeResize']=true;
        modal_data["props"] = { minHeight: "1vh", overlay: true };
        modal_data["content"] = 
			<CalendarModalPicker 
				onConfirm={confirmCalendar} 
				init={getStore("date_range_comps")?.initDate}
				last={getStore("date_range_comps")?.lastDate}
				isRange={true}
				colors={ {
					"--calendar-primary-color":"var(--hrm_palette-blue-purple)",
					"--calendar-primary-backcolor":"var(--primary-light)",
					"--calendar-light-backcolor":"var(--hrm_palette-general-background-b)",
					"--calendar-primary-hover-backcolor":"var(--hrm_palette-blue-purple_100)",

					"--calendar-light-300":"var(--disabled)",
					"--calendar-light-200":"var(--dark-800)",
					"--calendar-light-100":"var(--dark-900)",
					"--calendar-dark-800":"var(--hrm_palette-blue-purple_100)",
					"--calendar-white-100":"var(--light-100)",
					"--calendar-white":"var(--dark-700)",
					
					"--calendar-selected_lbl_color":"var(--light-400)",
					
					"--calendar-selected_lbl_color":"var(--primary-blue--color-30)",
				  }}
			/>
        
        OpenModal(modal_data);
	}
	

	let dateRangeString = getStore("date_range_comps")?.initDate && parseDateMMDDYYYY(getStore("date_range_comps")?.initDate)  + "-" +parseDateMMDDYYYY(getStore("date_range_comps")?.lastDate);


	




	return (
		<div style={{
			maxHeight: "80vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect">
					{ "Movimientos de Nomina"}
				</p>
				<div className="flexSpace"/>
				<div>
					<div className={"filter_date_btn _dsplFlx"} onClick={openCalendar}>
						<div className="lbl date">
								{dateRangeString || "Fecha"}
						</div>
						<Svg name={"calendar"} color={"#66666"}/>
					</div>
				</div>
			</div>

			<div className=" acc_dtls" style={{marginTop: 10}}>
				<div className="_dsplFlx"  >
					<div className="code" style={{color: "#646cff"}}>
						{item?.name} 
					</div>
					<div className="name">
						{item?. unit}
					</div>
				</div>
			</div>
			
			
			<div className="_dsplFlx acc_dtls">
				
				<div className="flexSpace"/>
				<div className="_dsplFlx"  >
						<div className="code" style={{color: "var(--hrm_palette-item_coll_gray)"}}>
							{"Acumulado:"} 
						</div>
						<div className="name" style={{color: "var(--hrm_palette-inverse-background-b)"}}>
							${SumBalancePS(getStore("paystub_submayor_group"))?.toFixed(2)} 
						</div>
					</div>
			</div>




			
			<div className="_dsplFlx hdr_bar purple">
				<div className="tr_bar_30">
					Comprobante
				</div>
				<div className="tr_bar_20">
					Fecha
				</div>
				<div className="tr_bar_30">
					Documento
				</div>
				<div className="tr_bar_20">
					Amount
				</div>
			</div>

			<div className="scollVh subMHeight">
			{getStore("paystub_submayor_group") && ObjectKeys(getStore("paystub_submayor_group"))?.map((elId,ind43) => {

				let element = getStore("paystub_submayor_group")[elId];
				return (
					<SubMEmployeeItm
						key={ind43}
						element={element}
						close={close}
						updObserve={updObs}
					/>
				)
				
			})}
			</div>
		</div>
	);
};

export default ViewComprobante;



const SubMEmployeeItm = ({element, close, updObserve}) => {

	
	const rmvOperatIds =  () => {

		delete_Comprobante(element.operations, close);
		//delete_ignore_Comprobante(element.operations, close);
	}

	const clearErrors =  () => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx">
				<Svg 
					name={"alert"} 
					color={"var(--hrm_palette-selected-nav-text)"}
				/>
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Peligro va a eliminar registros contables!!!"}
			</h4>
		</div>
		modaldata["content"] = <DeleteAlert 
			label={titleCm} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={"los registros estan corruptos pero debe saber que no podra recuperarlos"} 
			btnConfirm={"OK"}
			confirm={rmvOperatIds}
		/>
		OpenModal(modaldata);
	}


	
	
	if(!element?.["comprobanteId"] || element?.["balance"]===0){
		return (
			<div className="_dsplFlx hdr_bar" >
				<div className="tr_bar_90">
					<div className="name comprobante_id"  style={{color:"var(--hrm_palette-selected-nav-text)"}}>
						El registro contiene errores
					</div>
				</div>
				<div className="tr_bar_10">
					<div className="icon" onClick={()=>clearErrors()}>
						<Svg name={"outline_delete"} color={"var(--hrm_palette-selected-nav-text)"}/>
					</div>
				</div>
			</div>
		)
	}
	return(
		<div className="_dsplFlx hdr_bar" >
			<div className="tr_bar_30 ">
						
				<NavLink to={{
						pathname: "/accounting-ledger" ,
						search: `?cId=${element?.["comprobanteId"]}`
					}}>
						<div className=" comprobante_id" onClick={()=>close(element)}>
								{element.comprobanteId}
						</div>
				</NavLink>
			</div>	
			
			<div className="tr_bar_20">
				{element.date && parseDateMMDDYYYY(element.date)}
			</div>
			
			<div className="tr_bar_30">
				{element.document}
			</div>
			<div className="tr_bar_20">
				${(element.balance*1)?.toFixed(2)}
			</div>
		</div>
	)

}




const SumBalance2 = (obj) => {
	let balance = 0;
	obj && ObjectKeys(obj)?.map((flds, indE)=>{
		let amount = (obj[flds].balance*1);
		balance =  parseFloatToDecimal(balance,2)*1 + parseFloatToDecimal(amount,2)*1;
	});
	return  balance;
}  
